440	// parseRegistryVersion accepts exactly the integer literal of FormatVersion.
441	// Other integers report an unsupported version; anything else (strings,
442	// fractions, exponents, booleans, null, arrays, objects) is a type error.
443	func parseRegistryVersion(raw json.RawMessage) (int, error) {
444		token := string(bytes.TrimSpace(raw))
445		if isJSONInteger(token) {
446			if token == strconv.Itoa(FormatVersion) {
447				return FormatVersion, nil
448			}
449			return 0, fmt.Errorf("unsupported registry version: got %s, want %d", token, FormatVersion)
450		}
451		return 0, &FormatError{Field: "version", Reason: fmt.Sprintf("must be the integer %d, not %s", FormatVersion, token)}
452	}
453	
454	// parseRegistryRecord validates one batches element: a JSON object with
455	// exactly the four required lowercase fields, text fields as JSON strings
456	// and quantity as a strict JSON integer in 1..MaxQuantity. pos is the
457	// record's 1-based position in the batches array.
458	//
459	// The structural rules (member names, strict string decoding, quantity
460	// range) are shared with parseManifestRecord; only this source's reporting
461	// differs: problems are surfaced as *FormatError with registry wording, a
462	// duplicated member anywhere in the object outranks an unknown one, and
463	// text values are read verbatim — validate handles the empty-string case.
464	// A member name that cannot be decoded is reported as an invalid field name
465	// (keyEncodingReason), ahead of the duplicate/unknown scan, with the batch
466	// id attached under the same unambiguity rule as every other record error.
467	func parseRegistryRecord(raw json.RawMessage, pos int) (Batch, error) {
468		var b Batch
469		fields, badKey, err := parseObjectFields(raw)
470		if err != nil {
471			return b, &FormatError{Position: pos, Reason: "record must be a JSON object holding exactly \"batch\", \"product\", \"quantity\" and \"unit\""}
472		}
473		// The batch id is attached to errors only when it is unambiguous:
474		// exactly one "batch" member carrying a JSON string whose decoded text
475		// is valid UTF-8. When the "batch" member itself is duplicated, or its
476		// bytes are not valid UTF-8, no id (and never a U+FFFD replacement) is
477		// picked arbitrarily.
478		batchID := unambiguousBatchID(fields, textVerbatim)
479		if badKey {
480			return Batch{}, &FormatError{Position: pos, Batch: batchID, Reason: keyEncodingReason}
481		}
482		fail := func(field, reason string) (Batch, error) {
483			return Batch{}, &FormatError{Position: pos, Batch: batchID, Field: field, Reason: reason}
484		}
485	
486		switch fault := checkRecordMembers(fields, true); fault.kind {
487		case faultDuplicate:
488			return fail(fault.field, "field appears more than once; duplicate fields are not allowed")
489		case faultUnknown:
490			return fail(fault.field, "unknown field; only \"batch\", \"product\", \"quantity\" and \"unit\" are allowed")
491		}
492	
493		text := func(name string) (string, error) {
494			rawValue, ok := findField(fields, name)
495			value, problem, _ := decodeRecordText(rawValue, ok, textVerbatim)
496			switch problem {
497			case fieldMissing:
498				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "required field is missing"}
499			case fieldEncoding:
500				return "", &FormatError{Position: pos, Batch: batchID, Field: name,
501					Reason: "must be valid UTF-8 text: malformed bytes or lone surrogate escapes are rejected instead of being replaced with U+FFFD"}
502			case fieldNotString:
503				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
504			}
505			return value, nil
506		}
507		if b.Batch, err = text("batch"); err != nil {
508			return Batch{}, err
509		}
510		if b.Product, err = text("product"); err != nil {
511			return Batch{}, err
512		}
513		if b.Unit, err = text("unit"); err != nil {
514			return Batch{}, err
515		}
516		quantityRaw, ok := findField(fields, "quantity")
517		if !ok {
518			return fail("quantity", "required field is missing")
519		}
520		b.Quantity, err = registryQuantityError(bytes.TrimSpace(quantityRaw))
521		if err != nil {
522			return fail("quantity", err.Error())
523		}
524		return b, nil
525	}
