527	// isJSONInteger reports whether token is a JSON number literal without
528	// fraction or exponent. The token comes from validated JSON, so leading
529	// zeros cannot hide extra digits.
530	func isJSONInteger(token string) bool {
531		if token == "" {
532			return false
533		}
534		if token[0] == '-' {
535			token = token[1:]
536		}
537		if token == "" {
538			return false
539		}
540		for i := 0; i < len(token); i++ {
541			if token[i] < '0' || token[i] > '9' {
542				return false
543			}
544		}
545		return true
546	}
547	
548	// objectField is one member of a JSON object in source order; the key is
549	// the decoded JSON string, so escaped spellings compare by meaning.
550	type objectField struct {
551		key   string
552		value json.RawMessage
553	}
554	
555	// parseObjectFields decodes a single JSON object value into its members in
556	// source order, keeping duplicates visible for the caller to reject. Keys
557	// are re-scanned strictly: encoding/json would otherwise hand back U+FFFD
558	// substitutions for malformed key bytes.
559	//
560	// A member whose name cannot be decoded — malformed UTF-8 bytes or a lone
561	// surrogate escape — is reported through the badKey flag and dropped from
562	// the returned list: the substituted text encoding/json produced must never
563	// be treated as a real name, where it could collide with a genuine field or
564	// be misreported as an unknown field. Scanning still continues past such a
565	// member (its value is consumed normally) so every other member, a valid
566	// "batch" among them, stays visible to the caller's batch-id rule. The
567	// returned error is reserved for structural problems: the value not being an
568	// object, or malformed JSON inside it.
569	func parseObjectFields(raw []byte) (fields []objectField, badKey bool, err error) {
570		trimmed := bytes.TrimSpace(raw)
571		if len(trimmed) == 0 || trimmed[0] != '{' {
572			return nil, false, errors.New("value is not a JSON object")
573		}
574		dec := json.NewDecoder(bytes.NewReader(trimmed))
575		if _, err := dec.Token(); err != nil { // opening brace
576			return nil, false, err
577		}
578		for dec.More() {
579			keyStart := dec.InputOffset()
580			tok, err := dec.Token()
581			keyEnd := dec.InputOffset()
582			if err != nil {
583				return nil, false, err
584			}
585			key, ok := tok.(string)
586			if !ok {
587				return nil, false, errors.New("object keys must be JSON strings")
588			}
589			_, keyErr := unmarshalStringStrict(keyTokenBytes(trimmed, int(keyStart), int(keyEnd)))
590			var value json.RawMessage
591			if err := dec.Decode(&value); err != nil {
592				return nil, false, err
593			}
594			if keyErr != nil {
595				if errors.Is(keyErr, errStringEncoding) {
596					badKey = true
597					continue
598				}
599				return nil, false, keyErr
600			}
601			fields = append(fields, objectField{key: key, value: value})
602		}
603		if _, err := dec.Token(); err != nil { // closing brace
604			return nil, false, err
605		}
606		return fields, badKey, nil
607	}
608	
609	// trimJSONSpace strips only the four JSON whitespace bytes (space, tab,
610	// carriage return, newline). bytes.TrimSpace would also remove U+000B and
611	// other Unicode whitespace, which is illegal around a JSON token and must
612	// therefore be rejected rather than ignored.
613	func trimJSONSpace(b []byte) []byte {
614		isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\n' }
615		for len(b) > 0 && isSpace(b[0]) {
616			b = b[1:]
617		}
618		for len(b) > 0 && isSpace(b[len(b)-1]) {
619			b = b[:len(b)-1]
620		}
621		return b
622	}
623	
624	// keyTokenBytes isolates one key token inside trimmed[start:end]. The
625	// decoder reports the offset just after the preceding token (so the span
626	// may still contain a separating comma and whitespace), hence the left trim.
627	func keyTokenBytes(trimmed []byte, start, end int) []byte {
628		return bytes.TrimLeft(trimmed[start:end], " \t\r\n,")
629	}
