664	// storedDuplicateID reports the first batch id held by two records of the
665	// registry as handed in, scanning in stored order: Batch is that id, First
666	// the 1-based position of its first record and Second the position of its
667	// earliest repeat. It returns nil when every stored id is unique. Ids compare
668	// byte for byte, so "B1", "b1" and " B1 " are different ids.
669	//
670	// Register and Import run this check because a Go caller may hand them a
671	// Registry assembled directly — without Load — whose records already share an
672	// id. Neither entry point may then treat one of those records as the id's
673	// record (confirming a repeat against it, conflicting with it or appending
674	// next to it), and neither may repair the registry by dropping or merging a
675	// record: the only honest answer is the DuplicateIDError Load would have
676	// raised.
677	func storedDuplicateID(reg *Registry) *DuplicateIDError {
678		seen := make(map[string]int, len(reg.Batches))
679		for i, b := range reg.Batches {
680			pos := i + 1
681			if first, dup := seen[b.Batch]; dup {
682				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
683			}
684			seen[b.Batch] = pos
685		}
686		return nil
687	}
688	
689	func validate(reg *Registry) error {
690		seen := make(map[string]int, len(reg.Batches))
691		for i, b := range reg.Batches {
692			pos := i + 1
693			if b.Batch == "" || b.Product == "" || b.Unit == "" {
694				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
695			}
696			if b.Quantity <= 0 {
697				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
698			}
699			if first, dup := seen[b.Batch]; dup {
700				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
701			}
702			seen[b.Batch] = pos
703		}
704		return nil
705	}
