707	// ManifestRecordError reports a manifest record that is structurally invalid
708	// or carries a quantity outside the accepted range. Position is the record's
709	// 1-based position in the manifest.
710	type ManifestRecordError struct {
711		Position int
712		Batch    string // normalized batch id when available, otherwise ""
713		Reason   string
714	}
715	
716	func (e *ManifestRecordError) Error() string {
717		if e.Batch != "" {
718			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
719		}
720		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
721	}
