723	// ManifestConflictError reports that a manifest record disagrees with the
724	// record already registered, or introduced earlier in the same manifest,
725	// under the same batch id. Position is the record's 1-based position in the
726	// manifest and Fields lists every differing member among "product",
727	// "quantity" and "unit" in that order.
728	type ManifestConflictError struct {
729		Position int
730		Batch    string
731		Fields   []string
732		Source   string // "registry" or "manifest"
733		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
734	}
735	
736	func (e *ManifestConflictError) Error() string {
737		if e.Source == "manifest" {
738			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
739				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
740		}
741		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
742			e.Position, e.Batch, strings.Join(e.Fields, ", "))
743	}
