745	// ParseManifest decodes data as a non-empty JSON array holding exactly the
746	// four required fields batch, product, quantity and unit per element. The
747	// three text fields must be JSON strings that are not blank after trimming;
748	// quantity must be a JSON integer (no strings, fractions or exponents) in
749	// the range 1..MaxQuantity. An empty file, empty array, non-array document
750	// or any malformed record is rejected. The manifest bytes are never written.
751	func ParseManifest(data []byte) ([]Input, error) {
752		trimmed := bytes.TrimSpace(data)
753		if len(trimmed) == 0 {
754			return nil, errors.New("manifest file is empty")
755		}
756		if trimmed[0] != '[' {
757			return nil, errors.New("manifest must be a non-empty JSON array of records")
758		}
759	
760		var elems []json.RawMessage
761		dec := json.NewDecoder(bytes.NewReader(data))
762		if err := dec.Decode(&elems); err != nil {
763			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
764		}
765		var extra json.RawMessage
766		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
767			if err == nil {
768				return nil, errors.New("manifest has unexpected data after the array")
769			}
770			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
771		}
772		if len(elems) == 0 {
773			return nil, errors.New("manifest must contain at least one record")
774		}
775	
776		inputs := make([]Input, 0, len(elems))
777		for i, raw := range elems {
778			pos := i + 1
779			in, err := parseManifestRecord(raw)
780			if err != nil {
781				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
782			}
783			inputs = append(inputs, in)
784		}
785		return inputs, nil
786	}
787	
788	// batchRecordFields are the only members a batch record may carry, in the
789	// registry file and in an import manifest alike.
790	var batchRecordFields = map[string]struct{}{
791		"batch": {}, "product": {}, "quantity": {}, "unit": {},
792	}
793	
794	// parseManifestRecord validates one manifest element: it must be a JSON
795	// object with exactly the four required keys, text fields as non-blank,
796	// valid UTF-8 strings and quantity as a strict JSON integer. The members
797	// are scanned with parseObjectFields (strict key decoding, duplicates kept
798	// visible) rather than a lenient map unmarshal, so malformed key or value
799	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
800	// fail — an unknown, duplicated or case-mismatched field included — the
801	// returned Input carries the normalized batch id whenever exactly one
802	// "batch" member holds valid, non-blank text, so the caller can name the
803	// batch in the error; otherwise it stays empty.
804	//
805	// The structural rules are shared with parseRegistryRecord; this source's
806	// own choices are: member-name anomalies are reported in source order
807	// (unknown and duplicate carry equal weight), text is trimmed and must stay
808	// non-empty, and reasons use manifest wording (including *EncodingError for
809	// malformed text). A member name that cannot be decoded fails the record
810	// with keyEncodingReason before the source-order anomaly scan — the
811	// U+FFFD-substituted text is never judged as an unknown or duplicate name.
812	func parseManifestRecord(raw json.RawMessage) (Input, error) {
813		var in Input
814		members, badKey, err := parseObjectFields(raw)
815		if err != nil {
816			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
817		}
818		// Attach the batch id to whatever error this record raises, but only when
819		// it is unambiguous: exactly one "batch" member (compared after JSON key
820		// decoding, so an escaped respelling counts as the same field) carrying a
821		// JSON string whose decoded text is valid UTF-8 and non-blank once
822		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
823		// member leaves the id out — never a U+FFFD substitution, and never one
824		// of two duplicate values picked arbitrarily, even when both are equal.
825		// Where the "batch" member sits relative to the offending field does not
826		// matter.
827		in.Batch = unambiguousBatchID(members, textTrimmed)
828	
829		// A member name that cannot be decoded is a name-encoding problem, never
830		// an unknown field: the substituted text is not a real name.
831		if badKey {
832			return in, errors.New(keyEncodingReason)
833		}
834	
835		// Manifest member-name problems are reported in source order: the first
836		// unknown name or first repeat fails the record.
837		switch fault := checkRecordMembers(members, false); fault.kind {
838		case faultUnknown:
839			return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", fault.field)
840		case faultDuplicate:
841			return in, fmt.Errorf("record lists field %q more than once", fault.field)
842		}
843	
844		textField := func(name string) (string, error) {
845			rawValue, found := findField(members, name)
846			value, problem, cause := decodeRecordText(rawValue, found, textTrimmed)
847			switch problem {
848			case fieldMissing:
849				return "", fmt.Errorf("missing required field %q", name)
850			case fieldNotString:
851				return "", fmt.Errorf("field %q must be a JSON string", name)
852			case fieldEncoding:
853				return "", &EncodingError{Field: name}
854			case fieldBlank:
855				return "", fmt.Errorf("field %q must not be blank: %w", name, cause)
856			}
857			return value, nil
858		}
859	
860		in.Batch, err = textField("batch")
861		if err != nil {
862			return in, err
863		}
864		in.Product, err = textField("product")
865		if err != nil {
866			return in, err
867		}
868		in.Unit, err = textField("unit")
869		if err != nil {
870			return in, err
871		}
872		quantityRaw, ok := findField(members, "quantity")
873		if !ok {
874			return in, errors.New("missing required field \"quantity\"")
875		}
876		in.Quantity, err = manifestQuantityError(bytes.TrimSpace(quantityRaw))
877		if err != nil {
878			return in, err
879		}
880		return in, nil
881	}
