1021	// Register adds in to reg, or confirms the identical record already stored
1022	// under the same batch id. A batch id held by a record differing in product,
1023	// quantity or unit produces a *ConflictError and leaves reg untouched. A reg
1024	// that already holds two records under one batch id (only possible when it
1025	// was assembled directly, since Load refuses such files) produces a
1026	// *DuplicateIDError naming the id and the two 1-based stored positions —
1027	// reported after the version and input validations above, before any stored
1028	// record is consulted, and leaving reg exactly as handed in. The zero Outcome
1029	// is returned together with the error.
1030	func Register(reg *Registry, in Input) (Outcome, error) {
1031		if reg.Version != FormatVersion {
1032			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
1033		}
1034		// Register reports any empty text field before any encoding problem;
1035		// quantity problems come after both.
1036		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
1037		if _, bad := firstTextIssue(issues, textEmpty); bad {
1038			return Outcome{}, errors.New("batch, product and unit must be non-empty")
1039		}
1040		if issue, bad := firstTextIssue(issues, textEncoding); bad {
1041			return Outcome{}, &EncodingError{Field: issue.field}
1042		}
1043		if !quantityInRange(in.Quantity) {
1044			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
1045		}
1046		// A registry already holding two records under one id — possible only
1047		// when the caller assembled it directly, since Load refuses such files —
1048		// rejects the registration before the stored records are consulted: no
1049		// record may be picked as the id's record for a confirmation or a
1050		// conflict, and the ambiguous records are never merged or pruned.
1051		if dup := storedDuplicateID(reg); dup != nil {
1052			return Outcome{}, dup
1053		}
1054		for _, b := range reg.Batches {
1055			if b.Batch != in.Batch {
1056				continue
1057			}
1058			if diffs := diffFields(b, in); len(diffs) > 0 {
1059				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
1060			}
1061			return Outcome{Batch: b, Created: false}, nil
1062		}
1063		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
1064		reg.Batches = append(reg.Batches, b)
1065		return Outcome{Batch: b, Created: true}, nil
1066	}
