package batchreg

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"unicode/utf8"
)

// This file holds the single-record rules shared by the two on-disk sources:
// the registry file (decode, where stored text is already authoritative) and
// an import manifest (ParseManifest, where text is normalized on the way in).
// Both sources accept exactly the same four lowercase fields with the same
// strict JSON decoding — case-sensitive names, escaped spellings counted,
// duplicates visible, strict UTF-8 and strict JSON-integer quantities. The
// source-specific differences live in the callers:
//
//   - text policy: registry records are read verbatim (an empty string is a
//     format-level problem handled later by validate), while manifest text is
//     trimmed and must stay non-empty;
//   - which problem is reported first when one object has several: registry
//     records reject any duplicated field before an unknown one, manifest
//     records reject whichever anomaly appears first in source order;
//   - error types and reason wording, which remain owned by each caller.
type textPolicy int

const (
	textVerbatim textPolicy = iota // registry record: decode, keep as written
	textTrimmed                    // manifest record: trim ends, reject blank
)

// keyEncodingReason is the shared reason sentence for a member NAME that
// cannot be decoded (malformed UTF-8 bytes or a lone surrogate escape in the
// JSON string source). It is deliberately distinct from the two neighboring
// causes: a field VALUE with bad encoding ("must be valid UTF-8 text" /
// *EncodingError, naming the field) and a record that is not an object at
// all ("record must be a JSON object"). The offending bytes are never
// echoed: decoding them would substitute U+FFFD and make distinct names
// collide, and the substituted text must never be mistaken for a real name.
const keyEncodingReason = "a field name contains bytes that are not valid UTF-8 or holds a lone surrogate escape; the name is rejected instead of being replaced with U+FFFD"

// unambiguousBatchID returns the record's batch id only when it can be
// determined uniquely and reliably: exactly one "batch" member (counted after
// JSON key decoding, so an escaped respelling is the same member) holding one
// JSON string whose decoded text is valid UTF-8 and, under textTrimmed,
// non-blank after trimming. A missing, duplicated, mistyped, malformed or
// blank member yields "" — never a U+FFFD substitution and never one of two
// repeated values picked arbitrarily. The trimmed policy returns the
// normalized id; the verbatim policy returns the decoded text untouched.
func unambiguousBatchID(fields []objectField, policy textPolicy) string {
	if countField(fields, "batch") != 1 {
		return ""
	}
	raw, ok := findField(fields, "batch")
	if !ok {
		return ""
	}
	id, err := unmarshalStringStrict(raw)
	if err != nil {
		return ""
	}
	if policy == textTrimmed {
		normalized, err := NormalizeField(id)
		if err != nil {
			return ""
		}
		id = normalized
	}
	return id
}

// memberFault identifies one structural problem with an object's field names.
type memberFaultKind int

const (
	faultNone memberFaultKind = iota
	faultDuplicate
	faultUnknown
)

type memberFault struct {
	field string
	kind  memberFaultKind
}

// checkRecordMembers validates the member names of one batch record against
// batchRecordFields. With duplicatesFirst it reports the first member name
// that repeats anywhere in the object, and only reports an unknown member
// when nothing is repeated — the registry file rule. Otherwise it reports
// the first anomaly encountered in source order, be it an unknown member or
// a repeat — the manifest rule. In source order, an unknown name outranks a
// repeat on the same member, matching the original per-member scan. Repeated
// keys are detected on the decoded name, so a field hidden behind a JSON
// escape is the same member.
func checkRecordMembers(fields []objectField, duplicatesFirst bool) memberFault {
	seen := make(map[string]struct{}, len(fields))
	var firstDuplicate, firstUnknown memberFault
	for _, f := range fields {
		_, known := batchRecordFields[f.key]
		_, repeated := seen[f.key]
		seen[f.key] = struct{}{}
		if !duplicatesFirst {
			if !known {
				return memberFault{field: f.key, kind: faultUnknown}
			}
			if repeated {
				return memberFault{field: f.key, kind: faultDuplicate}
			}
			continue
		}
		if repeated && firstDuplicate.kind == faultNone {
			firstDuplicate = memberFault{field: f.key, kind: faultDuplicate}
		}
		if !known && firstUnknown.kind == faultNone {
			firstUnknown = memberFault{field: f.key, kind: faultUnknown}
		}
	}
	if duplicatesFirst {
		if firstDuplicate.kind != faultNone {
			return firstDuplicate
		}
		return firstUnknown
	}
	return memberFault{}
}

// fieldProblem classifies what is wrong with one text member's value,
// independently of the error wording each source presents.
type fieldProblem int

const (
	fieldOK fieldProblem = iota
	fieldMissing
	fieldNotString
	fieldEncoding
	fieldBlank
)

// decodeRecordText reads one text member. found says whether the member
// exists; raw is its JSON value. Under textVerbatim every syntactically and
// encoding-valid string is returned as written, including "". Under
// textTrimmed the value must additionally be non-empty after trimming
// (NormalizeField); in that case cause carries NormalizeField's error so the
// caller can keep the established reason wording.
func decodeRecordText(raw json.RawMessage, found bool, policy textPolicy) (value string, problem fieldProblem, cause error) {
	if !found {
		return "", fieldMissing, nil
	}
	if trimmed := bytes.TrimSpace(raw); len(trimmed) == 0 || trimmed[0] != '"' {
		return "", fieldNotString, nil
	}
	value, err := unmarshalStringStrict(raw)
	if errors.Is(err, errStringEncoding) {
		return "", fieldEncoding, nil
	}
	if err != nil {
		return "", fieldNotString, nil
	}
	if policy == textTrimmed {
		normalized, normErr := NormalizeField(value)
		if normErr != nil {
			// After strict decoding the only remaining failure is a blank
			// result, but keep the cause rather than re-stating its text.
			return "", fieldBlank, normErr
		}
		value = normalized
	}
	return value, fieldOK, nil
}

// quantityShape classifies a JSON quantity token without assigning source-
// specific wording. The token is the trimmed raw JSON value; the callers
// decide how each class is phrased for registry files versus manifests.
type quantityShape int

const (
	qtyValid       quantityShape = iota
	qtyNotNumeric                // value does not even start as a JSON number digit
	qtyFractional                // digits followed by '.', 'e' or another non-digit
	qtyLeadingZero               // "01": no conforming JSON document can reach this
	qtyOutOfRange                // all digits, but outside signed 64-bit range
	qtyZero
)

// classifyJSONQuantity is the shared numeric rule: a strict JSON integer
// token (no sign, fraction or exponent) in 1..MaxQuantity. It only inspects
// token shape and range — never the surrounding object — so both on-disk
// sources and every future caller maintain one quantity definition.
func classifyJSONQuantity(token []byte) (int64, quantityShape) {
	if len(token) == 0 || token[0] < '0' || token[0] > '9' {
		return 0, qtyNotNumeric
	}
	for _, c := range token {
		if c < '0' || c > '9' {
			return 0, qtyFractional
		}
	}
	if len(token) > 1 && token[0] == '0' {
		return 0, qtyLeadingZero
	}
	value, err := strconv.ParseInt(string(token), 10, 64)
	if err != nil {
		return 0, qtyOutOfRange
	}
	if value == 0 {
		return 0, qtyZero
	}
	return value, qtyValid
}

// recordTextField is one of the three textual members every record carries.
type recordTextField struct {
	name  string
	value string
}

// recordTextFields lists batch, product and unit in the fixed order in which
// per-field problems are reported, so every validation entry point iterates
// the same three members.
func recordTextFields(batch, product, unit string) []recordTextField {
	return []recordTextField{
		{"batch", batch},
		{"product", product},
		{"unit", unit},
	}
}

// safeBatchIDForError returns id exactly when it may be cited in an error:
// non-empty and valid UTF-8. An empty or malformed id yields "" so no value
// and no U+FFFD substitution is ever invented to name a batch.
func safeBatchIDForError(id string) string {
	if id != "" && utf8.ValidString(id) {
		return id
	}
	return ""
}

// textIssueKind classifies one problem with an already-decoded text field.
type textIssueKind int

const (
	textEmpty    textIssueKind = iota // the empty string; whitespace-only text is not empty
	textEncoding                      // the bytes are not valid UTF-8
)

// textIssue is one problem with one text field of an already-decoded record.
type textIssue struct {
	field string // "batch", "product" or "unit"
	kind  textIssueKind
}

// inspectRecordText examines the three text fields of an already-decoded
// record and lists every problem found, in the fixed batch, product, unit
// field order with a field's encoding problem listed before its empty-string
// problem. Text is checked verbatim — no trimming, no case folding — so
// whitespace-only text counts as ordinary non-empty text. This is the single
// definition of the text rules for the three entry points that validate
// decoded records (Register, Import and Save); each of them picks which issue
// to report first according to its own documented ordering.
func inspectRecordText(batch, product, unit string) []textIssue {
	var issues []textIssue
	for _, tv := range recordTextFields(batch, product, unit) {
		if !utf8.ValidString(tv.value) {
			issues = append(issues, textIssue{field: tv.name, kind: textEncoding})
		}
		if tv.value == "" {
			issues = append(issues, textIssue{field: tv.name, kind: textEmpty})
		}
	}
	return issues
}

// firstTextIssue returns the first issue of the given kind, if any.
func firstTextIssue(issues []textIssue, kind textIssueKind) (textIssue, bool) {
	for _, issue := range issues {
		if issue.kind == kind {
			return issue, true
		}
	}
	return textIssue{}, false
}

// decodedQuantityProblem classifies an already-decoded quantity against the
// accepted 1..MaxQuantity window shared by every entry point.
type decodedQuantityProblem int

const (
	decodedQtyOK decodedQuantityProblem = iota
	decodedQtyNotPositive
	decodedQtyAboveMax
)

// classifyDecodedQuantity is the single quantity rule for already-decoded
// records; the callers decide how each class is phrased.
func classifyDecodedQuantity(quantity int64) decodedQuantityProblem {
	switch {
	case quantity <= 0:
		return decodedQtyNotPositive
	case quantity > MaxQuantity:
		return decodedQtyAboveMax
	default:
		return decodedQtyOK
	}
}

// quantityInRange reports whether an already-decoded quantity lies in the
// accepted 1..MaxQuantity window shared by every entry point.
func quantityInRange(quantity int64) bool {
	return classifyDecodedQuantity(quantity) == decodedQtyOK
}

// These wrappers keep the registry-specific reason strings next to the
// registry parser while sharing classifyJSONQuantity; the wording predates
// the shared classifier and must not change.
func registryQuantityError(token []byte) (int64, error) {
	value, shape := classifyJSONQuantity(token)
	switch shape {
	case qtyValid:
		return value, nil
	case qtyZero:
		return 0, errors.New("must be greater than zero")
	case qtyOutOfRange:
		return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
	case qtyLeadingZero:
		// No conforming JSON token reaches this branch (leading zeros fail the
		// document scan); historically such a digit run was parsed on its
		// numeric value, so keep that exact behavior.
		parsed, err := strconv.ParseInt(string(token), 10, 64)
		if err != nil {
			return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
		}
		if parsed == 0 {
			return 0, errors.New("must be greater than zero")
		}
		return parsed, nil
	default: // qtyNotNumeric, qtyFractional
		return 0, fmt.Errorf("must be a JSON integer between 1 and %d", MaxQuantity)
	}
}

// manifestQuantityError mirrors the manifest wording: non-numeric values and
// signed numbers point at the accepted range, while fractions, exponents and
// (defensively) leading zeros each keep their own sentence.
func manifestQuantityError(token []byte) (int64, error) {
	value, shape := classifyJSONQuantity(token)
	switch shape {
	case qtyValid:
		return value, nil
	case qtyZero:
		return 0, errors.New(`field "quantity" must be greater than zero`)
	case qtyLeadingZero:
		return 0, errors.New(`field "quantity" must be a JSON integer without leading zeros`)
	case qtyFractional:
		return 0, errors.New(`field "quantity" must be a JSON integer without sign, fraction or exponent`)
	case qtyOutOfRange:
		return 0, fmt.Errorf(`field %q must be an integer no greater than %d`, "quantity", MaxQuantity)
	default: // qtyNotNumeric
		return 0, fmt.Errorf(`field %q must be a JSON integer between 1 and %d`, "quantity", MaxQuantity)
	}
}

package main

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// End-to-end regression for the missing-directory-then-".." escape at the
// command boundary. store/batches.json is registered and store/missing does
// not exist; the --registry given on the command line is
// store/missing/../batches.json. That raw path reaches no file the way the
// kernel resolves names, so both commands must fail rather than report
// "created": a non-zero child exit code, stderr naming the complete
// user-supplied registry path and stating that the path first descends into a
// non-existent directory and then climbs back with "..", empty stdout, the
// existing registry left byte-for-byte and timestamp-for-timestamp with its
// original batch, no store/missing directory or replacement file created, no
// save temporary file left behind, and the import manifest kept read-only.
//
// Normal creation through a not-yet-existing parent without a ".." remains a
// successful registration, so the rejection is specific to the escape shape.
// The failure needs no injected fault, so the child runs the wrapped command
// with all save hooks healthy — this guards the command's own path check.

// missingEscapeCLIFixture builds root/store/batches.json (pinned, holding one
// OLD batch) with no store/missing, and returns the raw user registry path
// (assembled without lexical cleaning so "missing/.." survives), the real
// registry path and its pinned bytes/mtime.
func missingEscapeCLIFixture(t *testing.T) (root, userPath, registry string, content []byte, pinned time.Time) {
	t.Helper()
	root = t.TempDir()
	storeDir := filepath.Join(root, "store")
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	registry = filepath.Join(storeDir, "batches.json")
	writeFile(t, registry, `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`)
	content, pinned = pinRegistry(t, registry)
	userPath = strings.Join([]string{storeDir, "missing", "..", "batches.json"}, string(os.PathSeparator))
	return root, userPath, registry, content, pinned
}

// assertEscapeChildFailure checks the process contract shared by both
// commands: exit code 1, empty stdout, and stderr carrying the command prefix,
// the exact user registry path and the missing-directory/".." reason.
func assertEscapeChildFailure(t *testing.T, code int, stdout, stderr []byte, userPath string) {
	t.Helper()
	if code != 1 {
		t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
	}
	if len(bytes.TrimSpace(stdout)) != 0 {
		t.Fatalf("stdout must stay empty on the rejected path, got %q", stdout)
	}
	msg := string(stderr)
	for _, want := range []string{
		"govflow:",
		userPath,
		"does not exist",
		"..",
	} {
		if !strings.Contains(msg, want) {
			t.Errorf("stderr must contain %q:\n%s", want, msg)
		}
	}
	if strings.Contains(msg, `"status":"created"`) {
		t.Errorf("stderr must not carry a success payload:\n%s", msg)
	}
}

// assertEscapeFilesystemUntouched verifies the rejected command created
// nothing: the real registry keeps its pinned bytes/mtime and its OLD batch,
// store/missing is absent and no save temporary file survives anywhere.
// extraAllowed names files (besides the registry) the fixture legitimately
// holds, such as the read-only import manifest.
func assertEscapeFilesystemUntouched(t *testing.T, root, registry string, content []byte, pinned time.Time, extraAllowed ...string) {
	t.Helper()
	assertRegistryUntouched(t, registry, content, pinned)
	if got := readStoredBatches(t, registry); len(got) != 1 || got[0].Batch != "OLD" {
		t.Fatalf("registry must keep exactly OLD, got %+v", got)
	}
	missing := filepath.Join(root, "store", "missing")
	if _, err := os.Lstat(missing); !os.IsNotExist(err) {
		t.Fatalf("the rejected command must not create the missing directory, stat err=%v", err)
	}
	allowed := append([]string{"batches.json"}, extraAllowed...)
	assertNoSaveLeftovers(t, root, allowed...)
}

// batch-register of a legal NEW batch through the escape path fails the
// process contract instead of replacing the OLD registry with NEW.
func TestBatchRegisterCLIMissingDirDotDotRejected(t *testing.T) {
	root, userPath, registry, content, pinned := missingEscapeCLIFixture(t)

	code, stdout, stderr := runRegisterChild(t, userPath, faultNone, "", true)

	assertEscapeChildFailure(t, code, stdout, stderr, userPath)
	assertEscapeFilesystemUntouched(t, root, registry, content, pinned)
}

// batch-import of a manifest containing a NEW batch through the same path
// writes none of it: the manifest stays read-only and the registry keeps OLD.
func TestBatchImportCLIMissingDirDotDotRejectsWholeManifest(t *testing.T) {
	root, userPath, registry, content, pinned := missingEscapeCLIFixture(t)
	manifest := filepath.Join(root, "manifest.json")
	manifestJSON := `[{"batch":"NEW","product":"P-9","quantity":5,"unit":"box"}]`
	writeFile(t, manifest, manifestJSON)

	code, stdout, stderr := runImportChild(t, userPath, manifest, faultNone, "", true)

	assertEscapeChildFailure(t, code, stdout, stderr, userPath)
	assertEscapeFilesystemUntouched(t, root, registry, content, pinned, "manifest.json")
	if after, _ := os.ReadFile(manifest); string(after) != manifestJSON {
		t.Fatal("the read-only manifest was modified")
	}
}

// A relative --registry with the same directory relationship as the absolute
// one is rejected identically; this runs the command in-process with the
// working directory set to the fixture root.
func TestBatchCommandsCLIMissingDirDotDotRelativeRejected(t *testing.T) {
	root := t.TempDir()
	registry := filepath.Join(root, "store", "batches.json")
	writeFile(t, registry, `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`)
	content, pinned := pinRegistry(t, registry)
	manifest := filepath.Join(root, "manifest.json")
	manifestJSON := `[{"batch":"NEW","product":"P-9","quantity":5,"unit":"box"}]`
	writeFile(t, manifest, manifestJSON)
	t.Chdir(root)
	userPath := strings.Join([]string{"store", "missing", "..", "batches.json"}, string(os.PathSeparator))

	t.Run("register", func(t *testing.T) {
		var stdout bytes.Buffer
		err := runBatchRegister([]string{
			"--registry", userPath,
			"--batch", "NEW", "--product", "P-9", "--quantity", "5", "--unit", "box",
		}, &stdout)
		if err == nil {
			t.Fatal("registering through the relative escape path must fail")
		}
		if !strings.Contains(err.Error(), userPath) || !strings.Contains(err.Error(), "..") {
			t.Errorf("error %q must name the relative path and the \"..\" reason", err.Error())
		}
		if stdout.Len() != 0 {
			t.Fatalf("stdout must stay empty, got %q", stdout.String())
		}
		assertRegistryUntouched(t, registry, content, pinned)
	})
	t.Run("import", func(t *testing.T) {
		var stdout bytes.Buffer
		err := runBatchImport([]string{"--registry", userPath, "--input", manifest}, &stdout)
		if err == nil {
			t.Fatal("importing through the relative escape path must fail")
		}
		if !strings.Contains(err.Error(), userPath) || !strings.Contains(err.Error(), "..") {
			t.Errorf("error %q must name the relative path and the \"..\" reason", err.Error())
		}
		if stdout.Len() != 0 {
			t.Fatalf("stdout must stay empty, got %q", stdout.String())
		}
		assertRegistryUntouched(t, registry, content, pinned)
		if after, _ := os.ReadFile(manifest); string(after) != manifestJSON {
			t.Fatal("the read-only manifest was modified")
		}
	})
}

// Preserved normal behavior: a first registration into store/new/batches.json,
// whose parent does not exist but which never climbs back, creates the
// directory and the registry and reports created.
func TestBatchRegisterCLINewDirectoryWithoutDotDotStillCreated(t *testing.T) {
	root := t.TempDir()
	registry := filepath.Join(root, "store", "new", "batches.json")

	stdout, err := registerCLI(t, registry, "NEW", "P-9", "5", "box")
	if err != nil {
		t.Fatalf("a first registration in a new directory must succeed: %v", err)
	}
	if got := decodeRegisterResult(t, stdout); got.Status != "created" || got.Batch != "NEW" {
		t.Fatalf("unexpected result: %+v", got)
	}
	if got := readStoredBatches(t, registry); len(got) != 1 || got[0].Batch != "NEW" {
		t.Fatalf("the new registry must hold NEW, got %+v", got)
	}
	assertNoSaveLeftovers(t, filepath.Join(root, "store"), "batches.json")
}

package batchreg

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// This file is the regression net for the missing-directory-then-".." escape.
// With store/batches.json registered and store/missing absent, the user path
// store/missing/../batches.json does not name any file the way the kernel
// resolves names: the ".." cannot step out of "missing" while "missing" does
// not exist. A save that collapses the path lexically (or first creates
// "missing") would reach store/batches.json and overwrite the registry with
// just the new batch. The rule under guard is that Save refuses such a path
// before creating anything: the error names the user-supplied path and the
// reason, an existing same-named file keeps its bytes and modification time,
// no missing directory, registry file or temporary file appears, and the
// caller's submitted batches keep their content and order. Relative paths and
// the absolute paths with the same directory structure behave identically.
//
// Ordinary creation is preserved: a path whose parent merely does not exist
// without climbing back (store/new/batches.json) still creates the directory
// and the registry, and a ".." after a directory that really exists keeps
// resolving by real directory relations — including a directory symlink,
// covered in batchreg_dirsymlink_dotdot_test.go.

// missingDotDotRegistryJSON is the one-record registry the fixtures start
// with; a successful escape would leave only the new batch behind.
const missingDotDotRegistryJSON = `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`

// missingEscapeFixture builds
//
//	root/
//	  store/
//	    batches.json   (registry holding OLD, mtime pinned)
//
// with no store/missing directory, and returns root and the registry path.
func missingEscapeFixture(t *testing.T) (root, registry string, original []byte, pinned time.Time) {
	t.Helper()
	root = t.TempDir()
	storeDir := filepath.Join(root, "store")
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	registry = filepath.Join(storeDir, "batches.json")
	writeRegistry(t, registry, missingDotDotRegistryJSON)
	pinned = pinFile(t, registry)
	original, err := os.ReadFile(registry)
	if err != nil {
		t.Fatal(err)
	}
	return root, registry, original, pinned
}

// assertMissingDirAbsent fails if the missing directory named in the escape
// path was brought into existence by the rejected save.
func assertMissingDirAbsent(t *testing.T, root, rel string) {
	t.Helper()
	if _, err := os.Lstat(filepath.Join(root, rel)); !os.IsNotExist(err) {
		t.Fatalf("the rejected save must not create %s, stat err=%v", rel, err)
	}
}

// rawJoin joins components with the OS separator WITHOUT lexical cleaning, so
// the deliberately unresolvable "missing/.." segment reaches Save exactly as
// a user would type it (filepath.Join/Clean would erase it).
func rawJoin(parts ...string) string {
	return strings.Join(parts, string(os.PathSeparator))
}

// assertEscapeRejected checks the shared error contract: a non-nil error that
// quotes the exact user path, names the missing directory and says the path
// climbs back with "..".
func assertEscapeRejected(t *testing.T, err error, userPath, missingName string) {
	t.Helper()
	if err == nil {
		t.Fatal("Save must reject a path that descends into a missing directory and climbs back with \"..\"")
	}
	msg := err.Error()
	for _, want := range []string{
		userPath,
		"does not exist",
		"..",
		"not written",
	} {
		if !strings.Contains(msg, want) {
			t.Errorf("error %q must mention %q", msg, want)
		}
	}
	if missingName != "" && !strings.Contains(msg, missingName) {
		t.Errorf("error %q must name the missing directory %q", msg, missingName)
	}
}

// Saving a legal registry addressed through store/missing/../batches.json
// must fail while store/batches.json keeps OLD: exact bytes, pinned mtime, no
// store/missing directory, no replacement file anywhere and no temporary file.
// The submitted batches and their order are untouched.
func TestSaveRejectsMissingDirDotDotOverExistingRegistry(t *testing.T) {
	root, registry, original, pinned := missingEscapeFixture(t)
	userPath := rawJoin(root, "store", "missing", "..", "batches.json")

	submitted := []Batch{saveBatch("NEW", "P-9", 5, "box")}
	reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), submitted...)}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	after, statErr := os.ReadFile(registry)
	if statErr != nil {
		t.Fatalf("the existing registry must still be present: %v", statErr)
	}
	if !bytes.Equal(after, original) {
		t.Fatalf("the escape overwrote the existing registry:\nbefore %s\nafter  %s", original, after)
	}
	if info, err := os.Stat(registry); err != nil {
		t.Fatal(err)
	} else if !info.ModTime().Equal(pinned) {
		t.Fatalf("the escape moved the registry mtime: got %v want %v", info.ModTime(), pinned)
	}
	assertMissingDirAbsent(t, root, filepath.Join("store", "missing"))
	assertNoLeftoverTempFiles(t, root)
	assertBatchesEqual(t, reg.Batches, submitted)
	// The surviving registry still reads back with its single OLD record.
	assertBatchesEqual(t, mustLoad(t, registry).Batches,
		[]Batch{saveBatch("OLD", "P-1", 10, "kg")})
}

// Even with no same-named file at the lexically cleaned location, the path is
// not a place to create a fresh registry: the save is rejected and neither
// the file nor the missing directory appears.
func TestSaveRejectsMissingDirDotDotWithoutExistingFileCreatesNothing(t *testing.T) {
	root := t.TempDir()
	storeDir := filepath.Join(root, "store")
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	userPath := rawJoin(root, "store", "missing", "..", "fresh.json")

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	if _, statErr := os.Lstat(filepath.Join(storeDir, "fresh.json")); !os.IsNotExist(statErr) {
		t.Fatalf("no registry may be created at the cleaned name, stat err=%v", statErr)
	}
	assertMissingDirAbsent(t, root, filepath.Join("store", "missing"))
	if entries, err := os.ReadDir(storeDir); err != nil {
		t.Fatal(err)
	} else if len(entries) != 0 {
		t.Fatalf("the rejected save left entries in store: %v", entries)
	}
	assertNoLeftoverTempFiles(t, root)
}

// A path that climbs past the missing directory more than once
// (store/missing/../../root-file) is rejected just the same and creates
// nothing outside store either.
func TestSaveRejectsMissingDirDotDotClimbingPastParent(t *testing.T) {
	root := t.TempDir()
	storeDir := filepath.Join(root, "store")
	if err := os.MkdirAll(storeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	userPath := rawJoin(root, "store", "missing", "..", "..", "outside.json")

	reg := &Registry{Version: FormatVersion, Batches: []Batch{saveBatch("NEW", "P-9", 5, "box")}}
	err := Save(userPath, reg)

	assertEscapeRejected(t, err, userPath, "missing")
	for _, p := range []string{
