53	// runWrappedBatchRegister performs exactly one batch-register against the
54	// registry named in WRAP_REGISTRY with the record from WRAP_BATCH /
55	// WRAP_PRODUCT / WRAP_QUANTITY / WRAP_UNIT, optionally failing one save step
56	// as selected by WRAP_FAULT. Exit codes mimic the real command: 1 for a
57	// reported batch-register failure (message written to stderr like main does,
58	// usage text included for input errors), 3 for a harness problem inside the
59	// child, 0 for success.
60	func runWrappedBatchRegister() int {
61		registry := os.Getenv("WRAP_REGISTRY")
