64		// whose signature allows only an error; the parent treats code 3 as a
65		// harness failure rather than a command failure.
66		harnessExit := func(format string, args ...any) error {
67			fmt.Fprintf(os.Stderr, "wrap harness: "+format+"\n", args...)
68			os.Exit(3)
69			return nil
70		}
71		switch saveFault(os.Getenv("WRAP_FAULT")) {
72		case faultWrite:
73			// Part of the new content genuinely reaches the temporary file, then
74			// the write stops with the new table incomplete.
75			batchreg.WriteTempContent = func(f *os.File, data []byte) (int, error) {
76				half := len(data) / 2
